/**
 * Compliance: the AI Act pack, the GDPR pack and the control mapping, generated by the service from the application's
 * configuration in the console's language; the controller's own statements (the profile); snapshots of what was true on
 * a date and what changed between two of them. A support for the controller's assessment, never legal advice.
 */
import { useState } from 'preact/hooks'

import type {
  ComplianceBlock,
  ComplianceDiff,
  ComplianceLang,
  CompliancePack,
  CompliancePackName,
  ComplianceProfile,
  ComplianceSnapshot,
  ConsoleApplication,
} from '@client/core/types'
import { describe, forApp } from '../api'
import { dateTime, download } from '../format'
import { done, sparkle, toast } from '../magic'
import { setTitle, useLoad } from '../state'
import { Btn, Field, Hero, Panel, Seg, Switch, Tag } from '../ui'
import { Loads } from './common'
import { locale, t, type TextKey } from '../i18n'

const PACKS: readonly CompliancePackName[] = ['ai-act', 'gdpr', 'controls']
const PACK_LABEL: Record<CompliancePackName, TextKey> = { 'ai-act': 'cmp.pack.aiAct', gdpr: 'cmp.pack.gdpr', controls: 'cmp.pack.controls' }
const AREAS = ['biometrics', 'critical_infrastructure', 'education', 'employment', 'essential_services', 'law_enforcement', 'migration', 'justice_democracy'] as const
const PRACTICES = [
  'manipulation',
  'exploitation',
  'social_scoring',
  'crime_prediction',
  'facial_scraping',
  'emotion_workplace',
  'biometric_categorisation_sensitive',
  'realtime_biometric_identification',
] as const
const EXCEPTIONS = ['narrow_procedural', 'improve_human_result', 'detect_patterns', 'preparatory'] as const
const ROLES = ['provider', 'deployer', 'provider_deployer'] as const
const BASES = ['', 'consent', 'contract', 'legal_obligation', 'vital_interests', 'public_task', 'legitimate'] as const
const LEVEL_TONE: Record<string, '' | 'ok' | 'warn' | 'bad'> = {
  prohibited: 'bad',
  high_risk: 'warn',
  annex_iii_exempted: 'warn',
  limited_risk: '',
  minimal_risk: 'ok',
}

const lang = (): ComplianceLang => (locale() === 'it' ? 'it' : 'en')
const levelLabel = (level: string): string => t(`cmp.level.${level}` as TextKey)

export function Compliance({ app }: { app: ConsoleApplication }) {
  setTitle(t('tab.compliance'), app.name)
  const [pack, setPack] = useState<CompliancePackName>('ai-act')
  const [version, setVersion] = useState(0)
  return (
    <>
      <Hero title={t('tab.compliance')} sub={t('cmp.sub')} />
      <div class="callout warn" role="note">
        <span>{t('cmp.disclaimer')}</span>
      </div>
      <PackView app={app} pack={pack} setPack={setPack} version={version} />
      <div class="grid g2" style="margin-top:16px">
        <ProfileEditor app={app} onSaved={() => setVersion((v) => v + 1)} />
        <Snapshots app={app} pack={pack} />
      </div>
    </>
  )
}

function PackView(p: { app: ConsoleApplication; pack: CompliancePackName; setPack: (p: CompliancePackName) => void; version: number }) {
  const api = forApp(p.app.id)
  const l = lang()
  const load = useLoad(() => api.admin.compliance.pack(p.pack, l), [p.app.id, p.pack, l, p.version])
  const [busy, setBusy] = useState<string | null>(null)
  const name = `evokai-${p.app.slug}-${p.pack}-${l}`
  const save = async (format: 'md' | 'html' | 'json') => {
    setBusy(format)
    try {
      if (format === 'json') {
        const data = await api.admin.compliance.pack(p.pack, l)
        download(`${name}.json`, JSON.stringify(data, null, 2), 'application/json')
      } else {
        const text = await api.admin.compliance.packText(p.pack, format, l)
        download(`${name}.${format}`, text, format === 'md' ? 'text/markdown' : 'text/html')
      }
    } catch (err) {
      toast(t('cmp.notDownloaded'), describe(err), null)
    } finally {
      setBusy(null)
    }
  }
  const print = async () => {
    setBusy('print')
    try {
      const html = await api.admin.compliance.packText(p.pack, 'html', l)
      const url = URL.createObjectURL(new Blob([html], { type: 'text/html' }))
      window.open(url, '_blank', 'noopener')
      setTimeout(() => URL.revokeObjectURL(url), 60_000)
    } catch (err) {
      toast(t('cmp.notDownloaded'), describe(err), null)
    } finally {
      setBusy(null)
    }
  }
  return (
    <Panel
      title={<Seg options={PACKS} value={p.pack} onChange={p.setPack} labels={{ 'ai-act': t(PACK_LABEL['ai-act']), gdpr: t(PACK_LABEL.gdpr), controls: t(PACK_LABEL.controls) }} />}
      actions={
        <span style="display:flex;gap:6px;flex-wrap:wrap">
          <Btn sm kind="ghost" busy={busy === 'print' ? t('cmp.opening') : false} onClick={() => void print()}>
            {t('cmp.print')}
          </Btn>
          <Btn sm kind="ghost" busy={busy === 'html' ? t('cmp.downloading') : false} onClick={() => void save('html')}>
            {t('cmp.html')}
          </Btn>
          <Btn sm kind="ghost" busy={busy === 'md' ? t('cmp.downloading') : false} onClick={() => void save('md')}>
            {t('cmp.md')}
          </Btn>
          <Btn sm kind="ghost" busy={busy === 'json' ? t('cmp.downloading') : false} onClick={() => void save('json')}>
            JSON
          </Btn>
        </span>
      }
    >
      <Loads load={load} what={t('what.compliancePack')} panel={false}>
        {(data) => <PackDocument pack={data} />}
      </Loads>
    </Panel>
  )
}

function refs(keys: string[], nums: Map<string, number>) {
  return keys
    .filter((k) => nums.has(k))
    .map((k) => (
      <sup key={k} class="cmpfn">
        <a href={`#cmp-fn-${nums.get(k)}`}>{`[${nums.get(k)}]`}</a>
      </sup>
    ))
}

function Flag({ flag }: { flag?: string | undefined }) {
  if (flag === 'human') return <Tag tone="vi">{t('cmp.flag.human')}</Tag>
  if (flag === 'warn') return <Tag tone="warn">{t('cmp.flag.warn')}</Tag>
  return null
}

function PackDocument({ pack }: { pack: CompliancePack }) {
  const nums = new Map(pack.footnotes.map((f) => [f.key, f.n]))
  return (
    <article class="cmpdoc" lang={pack.lang}>
      <h2 class="cmpt">{pack.title}</h2>
      <p class="hint">{pack.subtitle}</p>
      {pack.classification ? (
        <p>
          <Tag tone={LEVEL_TONE[pack.classification.level] ?? ''} dot>
            {levelLabel(pack.classification.level)}
          </Tag>
        </p>
      ) : null}
      <dl class="cmpmeta">
        {pack.meta.map((m) => (
          <div key={m.label}>
            <dt>{m.label}</dt>
            <dd>{m.value}</dd>
          </div>
        ))}
      </dl>
      {pack.sections.map((s) => (
        <section key={s.id} id={`cmp-${s.id}`}>
          <h3>{s.title}</h3>
          {s.blocks.map((b) => (
            <Block key={b.id} b={b} nums={nums} />
          ))}
        </section>
      ))}
      <section class="cmpnotes">
        <h3>{t('cmp.sources')}</h3>
        <ol>
          {pack.footnotes.map((f) => (
            <li key={f.n} id={`cmp-fn-${f.n}`}>
              {f.text}
            </li>
          ))}
        </ol>
      </section>
    </article>
  )
}

function Block({ b, nums }: { b: ComplianceBlock; nums: Map<string, number> }) {
  const title = b.title ? <h4>{b.title}</h4> : null
  if (b.kind === 'p')
    return (
      <p class={b.human ? 'cmphuman' : ''}>
        {b.text}
        {refs(b.sources, nums)} {b.human ? <Flag flag="human" /> : null}
      </p>
    )
  if (b.kind === 'list')
    return (
      <>
        {title}
        <ul class="cmplist">
          {(b.items ?? []).map((i) => (
            <li key={i.id} data-flag={i.flag}>
              {i.text}
              {refs(i.sources, nums)} <Flag flag={i.flag} />
            </li>
          ))}
        </ul>
      </>
    )
  if (b.kind === 'fields')
    return (
      <>
        {title}
        <table class="tbl cmpfields">
          <tbody>
            {(b.items ?? []).map((i) => (
              <tr key={i.id} data-flag={i.flag}>
                <th scope="row">{i.cells?.[0]}</th>
                <td>
                  {i.cells?.[1]}
                  {refs(i.sources, nums)} <Flag flag={i.flag} />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </>
    )
  return (
    <>
      {title}
      <div class="tblwrap">
        <table class="tbl cmptable">
          <thead>
            <tr>
              {(b.columns ?? []).map((c) => (
                <th key={c} scope="col">
                  {c}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {(b.items ?? []).map((i) => (
              <tr key={i.id} data-flag={i.flag}>
                {(i.cells ?? []).map((c, n, all) => (
                  <td key={n}>
                    {c}
                    {n === all.length - 1 ? (
                      <>
                        {refs(i.sources, nums)} <Flag flag={i.flag} />
                      </>
                    ) : null}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </>
  )
}

// The controller's statements

const lines = (v: string): string[] =>
  v
    .split('\n')
    .map((x) => x.trim())
    .filter(Boolean)

function Checks<T extends string>(p: { options: readonly T[]; value: T[]; onChange: (v: T[]) => void; label: (o: T) => string }) {
  return (
    <div class="cmpchecks">
      {p.options.map((o) => (
        <label key={o} class="affix">
          <input
            type="checkbox"
            checked={p.value.includes(o)}
            onChange={(e) => p.onChange(e.currentTarget.checked ? [...p.value, o] : p.value.filter((x) => x !== o))}
          />
          <span>{p.label(o)}</span>
        </label>
      ))}
    </div>
  )
}

function Toggle(p: { on: boolean; onChange: (v: boolean) => void; label: string }) {
  return (
    <div class="cmptoggle">
      <Switch on={p.on} onChange={p.onChange} aria={p.label} />
      <span>{p.label}</span>
    </div>
  )
}

function ProfileEditor({ app, onSaved }: { app: ConsoleApplication; onSaved: () => void }) {
  const load = useLoad(() => forApp(app.id).admin.compliance.profile(), [app.id])
  return (
    <Loads load={load} what={t('what.complianceProfile')}>
      {(p) => <ProfileForm key={JSON.stringify(p.profile)} app={app} initial={p.profile} onSaved={onSaved} reload={load.reload} />}
    </Loads>
  )
}

type Profile = Required<ComplianceProfile>

function ProfileForm(p: { app: ConsoleApplication; initial: ComplianceProfile; onSaved: () => void; reload: () => Promise<void> }) {
  const [f, setF] = useState<Profile>(p.initial as Profile)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const ai = f.ai_act ?? {}
  const gd = f.gdpr ?? {}
  const set = (patch: Partial<Profile>) => setF({ ...f, ...patch })
  const setAi = (patch: Partial<NonNullable<Profile['ai_act']>>) => set({ ai_act: { ...ai, ...patch } })
  const setGd = (patch: Partial<NonNullable<Profile['gdpr']>>) => set({ gdpr: { ...gd, ...patch } })
  const text = (k: 'system_name' | 'system_description' | 'intended_purpose' | 'controller' | 'processor' | 'notes', area = false) => (
    <Field label={t(`cmp.f.${k}` as TextKey)}>
      {area ? (
        <textarea class="in" style="min-height:72px" value={f[k] ?? ''} onInput={(e) => set({ [k]: e.currentTarget.value })} />
      ) : (
        <input class="in" value={f[k] ?? ''} onInput={(e) => set({ [k]: e.currentTarget.value })} />
      )}
    </Field>
  )
  const list = (k: 'purposes' | 'data_subjects' | 'data_categories' | 'recipients') => (
    <Field label={t(`cmp.g.${k}` as TextKey)} hint={t('cmp.oneALine')}>
      <textarea class="in" style="min-height:56px" value={(gd[k] ?? []).join('\n')} onInput={(e) => setGd({ [k]: lines(e.currentTarget.value) })} />
    </Field>
  )
  const save = async (e: Event) => {
    const btn = e.currentTarget as Element
    setSaving(true)
    setError(null)
    try {
      await forApp(p.app.id).admin.compliance.putProfile(f)
      sparkle(btn)
      done(btn)
      toast(t('cmp.saved'), t('cmp.savedSub'))
      p.onSaved()
      await p.reload()
    } catch (err) {
      setError(describe(err))
    } finally {
      setSaving(false)
    }
  }
  const tri = (v: boolean | null | undefined) => (v === true ? 'yes' : v === false ? 'no' : 'unknown')
  const fromTri = (v: string) => (v === 'yes' ? true : v === 'no' ? false : null)
  return (
    <Panel
      title={t('cmp.profile')}
      actions={
        <Btn sm kind="pri" check busy={saving ? t('common.saving') : false} onClick={(e) => void save(e)}>
          {t('common.save')}
        </Btn>
      }
    >
      <p class="hint" style="margin-top:0">{t('cmp.profileHint')}</p>
      {error ? <div class="callout bad">{error}</div> : null}
      <h4>{t('cmp.h.system')}</h4>
      {text('system_name')}
      {text('system_description', true)}
      {text('intended_purpose', true)}
      {text('controller')}
      {text('processor')}
      <h4>{t('cmp.h.aiAct')}</h4>
      <Field label={t('cmp.a.role')}>
        <Seg
          options={ROLES}
          value={(ai.role ?? 'provider_deployer') as (typeof ROLES)[number]}
          onChange={(v) => setAi({ role: v })}
          labels={{ provider: t('cmp.role.provider'), deployer: t('cmp.role.deployer'), provider_deployer: t('cmp.role.provider_deployer') }}
        />
      </Field>
      <Field label={t('cmp.a.prohibited')} hint={t('cmp.a.prohibitedHint')}>
        <Checks options={PRACTICES} value={(ai.prohibited ?? []) as (typeof PRACTICES)[number][]} onChange={(v) => setAi({ prohibited: v })} label={(o) => t(`cmp.practice.${o}` as TextKey)} />
      </Field>
      <Field label={t('cmp.a.annex')} hint={t('cmp.a.annexHint')}>
        <Checks options={AREAS} value={(ai.annex_iii ?? []) as (typeof AREAS)[number][]} onChange={(v) => setAi({ annex_iii: v })} label={(o) => t(`cmp.area.${o}` as TextKey)} />
      </Field>
      <Field label={t('cmp.a.exceptions')} hint={t('cmp.a.exceptionsHint')}>
        <Checks options={EXCEPTIONS} value={(ai.exceptions ?? []) as (typeof EXCEPTIONS)[number][]} onChange={(v) => setAi({ exceptions: v })} label={(o) => t(`cmp.exception.${o}` as TextKey)} />
      </Field>
      <Toggle on={!!ai.profiling} onChange={(v) => setAi({ profiling: v })} label={t('cmp.a.profiling')} />
      <Toggle on={!!ai.safety_component} onChange={(v) => setAi({ safety_component: v })} label={t('cmp.a.safety')} />
      <Toggle on={!!ai.emotion_recognition} onChange={(v) => setAi({ emotion_recognition: v })} label={t('cmp.a.emotion')} />
      <Toggle on={!!ai.biometric_categorisation} onChange={(v) => setAi({ biometric_categorisation: v })} label={t('cmp.a.biometric')} />
      <Toggle on={!!ai.deep_fake} onChange={(v) => setAi({ deep_fake: v })} label={t('cmp.a.deepFake')} />
      <Toggle on={!!ai.public_interest_text} onChange={(v) => setAi({ public_interest_text: v })} label={t('cmp.a.publicText')} />
      <Field label={t('cmp.a.disclosure')}>
        <Seg
          options={['yes', 'no', 'unknown'] as const}
          value={tri(ai.disclosure_shown)}
          onChange={(v) => setAi({ disclosure_shown: fromTri(v) })}
          labels={{ yes: t('cmp.yes'), no: t('cmp.no'), unknown: t('cmp.unknown') }}
        />
      </Field>
      <h4>{t('cmp.h.gdpr')}</h4>
      {list('purposes')}
      <Field label={t('cmp.g.basis')}>
        <select class="in" value={gd.legal_basis ?? ''} onChange={(e) => setGd({ legal_basis: e.currentTarget.value as (typeof BASES)[number] })}>
          {BASES.map((b) => (
            <option key={b} value={b}>
              {t(`cmp.basis.${b || 'none'}` as TextKey)}
            </option>
          ))}
        </select>
      </Field>
      <Field label={t('cmp.g.basisNote')}>
        <input class="in" value={gd.legal_basis_note ?? ''} onInput={(e) => setGd({ legal_basis_note: e.currentTarget.value })} />
      </Field>
      {list('data_subjects')}
      {list('data_categories')}
      {list('recipients')}
      <Field label={t('cmp.g.transfers')}>
        <input class="in" value={gd.transfers_note ?? ''} onInput={(e) => setGd({ transfers_note: e.currentTarget.value })} />
      </Field>
      <Toggle on={!!gd.special_categories} onChange={(v) => setGd({ special_categories: v })} label={t('cmp.g.special')} />
      <Toggle on={!!gd.large_scale} onChange={(v) => setGd({ large_scale: v })} label={t('cmp.g.largeScale')} />
      <Toggle on={!!gd.vulnerable_subjects} onChange={(v) => setGd({ vulnerable_subjects: v })} label={t('cmp.g.vulnerable')} />
      <Toggle on={!!gd.systematic_monitoring} onChange={(v) => setGd({ systematic_monitoring: v })} label={t('cmp.g.monitoring')} />
      <Toggle on={!!gd.automated_decisions} onChange={(v) => setGd({ automated_decisions: v })} label={t('cmp.g.automated')} />
      <Field label={t('cmp.g.dpo')}>
        <Seg
          options={['yes', 'no', 'unknown'] as const}
          value={tri(gd.dpo_appointed)}
          onChange={(v) => setGd({ dpo_appointed: fromTri(v) })}
          labels={{ yes: t('cmp.yes'), no: t('cmp.no'), unknown: t('cmp.unknown') }}
        />
      </Field>
      {text('notes', true)}
    </Panel>
  )
}

// Snapshots and their diff

function Snapshots({ app, pack }: { app: ConsoleApplication; pack: CompliancePackName }) {
  const api = forApp(app.id)
  const load = useLoad(() => api.admin.compliance.snapshots(), [app.id])
  const [label, setLabel] = useState('')
  const [busy, setBusy] = useState(false)
  const [picked, setPicked] = useState<string[]>([])
  const [diff, setDiff] = useState<ComplianceDiff | null>(null)
  const take = async (e: Event) => {
    const btn = e.currentTarget as Element
    setBusy(true)
    try {
      const s = await api.admin.compliance.snapshot(label.trim())
      sparkle(btn)
      setLabel('')
      toast(t('cmp.snap.taken'), t('cmp.snap.takenSub', { level: levelLabel(s.classification) }))
      await load.reload()
    } catch (err) {
      toast(t('cmp.snap.notTaken'), describe(err), null)
    } finally {
      setBusy(false)
    }
  }
  const pick = (id: string, on: boolean) => {
    const next = on ? [...picked.filter((x) => x !== id), id].slice(-2) : picked.filter((x) => x !== id)
    setPicked(next)
    setDiff(null)
  }
  const compare = async () => {
    try {
      setDiff(await api.admin.compliance.diff(picked[0]!, picked[1]!, lang()))
    } catch (err) {
      toast(t('cmp.diff.failed'), describe(err), null)
    }
  }
  const save = async (s: ComplianceSnapshot) => {
    try {
      const html = await api.admin.compliance.snapshotText(s.id, pack, 'html', lang())
      download(`evokai-${app.slug}-${pack}-${s.id}-${lang()}.html`, html, 'text/html')
    } catch (err) {
      toast(t('cmp.notDownloaded'), describe(err), null)
    }
  }
  return (
    <Panel title={t('cmp.snapshots')}>
      <p class="hint" style="margin-top:0">{t('cmp.snap.hint')}</p>
      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px">
        <input class="in" style="flex:1;min-width:160px" value={label} placeholder={t('cmp.snap.label')} onInput={(e) => setLabel(e.currentTarget.value)} />
        <Btn kind="pri" busy={busy ? t('cmp.snap.taking') : false} onClick={(e) => void take(e)}>
          {t('cmp.snap.take')}
        </Btn>
      </div>
      <Loads load={load} what={t('what.complianceSnapshots')} panel={false}>
        {(items) =>
          items.length ? (
            <>
              <table class="tbl">
                <thead>
                  <tr>
                    <th scope="col">
                      <span class="sr">{t('cmp.diff.pick')}</span>
                    </th>
                    <th scope="col">{t('cmp.snap.when')}</th>
                    <th scope="col">{t('cmp.snap.labelCol')}</th>
                    <th scope="col">{t('cmp.snap.level')}</th>
                    <th scope="col">
                      <span class="sr">{t('cmp.html')}</span>
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {items.map((s) => (
                    <tr key={s.id}>
                      <td>
                        <input type="checkbox" aria-label={t('cmp.diff.pick')} checked={picked.includes(s.id)} onChange={(e) => pick(s.id, e.currentTarget.checked)} />
                      </td>
                      <td>{dateTime(s.createdAt)}</td>
                      <td>{s.label || t('fmt.none')}</td>
                      <td>
                        <Tag tone={LEVEL_TONE[s.classification] ?? ''}>{levelLabel(s.classification)}</Tag>
                      </td>
                      <td>
                        <Btn sm kind="ghost" onClick={() => void save(s)}>
                          {t('cmp.html')}
                        </Btn>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <div style="margin-top:10px">
                <Btn kind="ghost" disabled={picked.length !== 2} onClick={() => void compare()}>
                  {t('cmp.diff.compare')}
                </Btn>
              </div>
            </>
          ) : (
            <p class="hint">{t('cmp.snap.none')}</p>
          )
        }
      </Loads>
      {diff ? <DiffView d={diff} /> : null}
    </Panel>
  )
}

function DiffView({ d }: { d: ComplianceDiff }) {
  const c = d.packs['ai-act'].classification
  return (
    <div class="cmpdiff">
      <h4>{t('cmp.diff.title', { from: dateTime(d.from.createdAt), to: dateTime(d.to.createdAt) })}</h4>
      {c && c.before !== c.after ? (
        <div class="callout warn">
          <span>{t('cmp.diff.level', { before: levelLabel(c.before), after: levelLabel(c.after) })}</span>
        </div>
      ) : null}
      <p class="hint">{t('cmp.diff.counts', { statements: d.counts.statements, facts: d.counts.facts })}</p>
      {PACKS.map((name) => {
        const x = d.packs[name]
        if (!x.added.length && !x.removed.length && !x.changed.length) return null
        return (
          <section key={name}>
            <h5>{t(PACK_LABEL[name])}</h5>
            <ul class="cmplist">
              {x.added.map((a) => (
                <li key={`a${a.id}`} class="add">
                  <Tag tone="ok">{t('cmp.diff.added')}</Tag> {a.text}
                </li>
              ))}
              {x.removed.map((a) => (
                <li key={`r${a.id}`} class="del">
                  <Tag tone="bad">{t('cmp.diff.removed')}</Tag> {a.text}
                </li>
              ))}
              {x.changed.map((a) => (
                <li key={`c${a.id}`}>
                  <Tag tone="warn">{t('cmp.diff.changed')}</Tag> <del>{a.before}</del> {a.after}
                </li>
              ))}
            </ul>
          </section>
        )
      })}
    </div>
  )
}
